nextflow_process {

    name "Test Process SKANI_DIST"
    script "../main.nf"
    process "SKANI_DIST"

    tag "modules"
    tag "modules_nfcore"
    tag "skani"
    tag "skani/dist"

    // Dependencies
    tag "skani/sketch"

    setup {
        run("SKANI_SKETCH", alias: "SKANI_SKETCH1") {
            script "../../sketch/main.nf"
            process {
                """
                input[0] = [
                    [ id: 'test' ],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.gz", checkIfExists: true)
                    ]
                """
            }
        }

        run("SKANI_SKETCH", alias: "SKANI_SKETCH2") {
            script "../../sketch/main.nf"
            process {
                """
                input[0] = [
                    [ id: 'test2' ],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fasta/contigs.fasta", checkIfExists: true)
                    ]
                """
            }
        }
    }

    test("fasta.gz + fasta") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.gz", checkIfExists: true)
                    ]
                input[1] = [
                    [ id:'test2' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fasta/contigs.fasta", checkIfExists: true)
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("fasta.gz + fastq - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.gz", checkIfExists: true)
                    ]
                input[1] = [
                    [ id:'test2' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fasta/contigs.fasta", checkIfExists: true)
                    ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sketch + sketch") {
        when {
            process {
                """
                input[0] = SKANI_SKETCH1.out.sketch
                input[1] = SKANI_SKETCH2.out.sketch
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sketch + sketch - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = SKANI_SKETCH1.out.sketch
                input[1] = SKANI_SKETCH2.out.sketch
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

